           // Implement the logic to delete a company
       }

       public List<CompanyDTO> getAllCompanies() {
           // Implement the logic to get all companies
       }

       public CompanyDTO getCompanyById(String id) {
           // Implement the logic to get a company by ID
       }
   }

   @Service
   public class ContactService {
       private final ContactRepository contactRepository;

       // Constructor

       public ContactDTO createContact(String name, String mailId) {
           // Implement the logic to create a contact
       }

       public ContactDTO updateContact(String id, String name, String mailId) {
           // Implement the logic to update a contact
       }

       public String deleteContact(String id) {
           // Implement the logic to delete a contact
       }

       public List<ContactDTO> getAllContacts() {
           // Implement the logic to get all contacts
       }

       public ContactDTO getContactById(String id) {
