```javascript
const express = require('express');
const { v4: uuidv4 } = require('uuid');
const neo4j = require('neo4j-driver');

const app = express();
const port = 3000;

const driver = neo4j.driver('bolt://localhost:7687', neo4j.auth.basic('neo4j', 'your_password'));

app.use(express.json());

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.post('/word', async (req, res) => {
  const session = driver.session();
  const { name, meaning, synonyms } = req.body;
  const wordId = uuidv4();

  try {
    const result = await session.run(
      'CREATE (w:Word {id: $id, name: $name, meaning: $meaning}) RETURN w',
      { id: wordId, name, meaning }
    );

    // Create relationships with synonyms
    if (synonyms && synonyms.length > 0) {
      for (const synonymId of synonyms) {
        await session.run(
          'MATCH (w1:Word {id: $id1}), (w2:Word {id: $id2}) CREATE (w1)-[:SYNONYM_OF]->(w2)',
          { id1: wordId, id2: synonymId }
        );
      }
    }

    res.status(201).json({ id: wordId, name, meaning, synonyms });
  } catch (error) {
    console.error('Error creating word:', error);
    res.status(500).send('Internal Server Error');
  } finally {
    await session.close();
  }
});

app.get('/word/:id', async (req, res) => {
  const session = driver.session();
  const wordId = req.params.id;

  try {
    const result = await session.run(
      'MATCH (w:Word {id: $id}) RETURN w',
      { id: wordId }
    );

    const word = result.records[0].get('w').properties;
    res.json(word);
  } catch (error) {
    console.error('Error retrieving word:', error);
    res.status(500).send('Internal Server Error');
  } finally {
    await session.close();
  }
});

app.listen(port, () => {
  console.log(`App listening at http://localhost:${port}`);
});
```

Make sure to replace `'your_password'` in the `neo4j.driver()` call with your actual Neo4j password.

5. Run your Node.js server:

```bash
node index.js
```

