```javascript
// Import required libraries
const express = require('express');
const axios = require('axios');

// Create an Express application
const app = express();
const port = 3000;

// Define a route to fetch data from GraphQL endpoint
app.get('/', async (req, res) => {
    try {
        // Make a request to the GraphQL endpoint
        const response = await axios.post('https://example.com/graphql', {
            query: `
                query {
                    posts {
                        id
                        title
                        body
                    }
                }
            `
        });

        // Extract data from the response
        const posts = response.data.data.posts;

        // Render HTML with the fetched data
        const html = `
            <html>
                <head>
                    <title>Posts</title>
                </head>
                <body>
                    <h1>Posts</h1>
                    <ul>
                        ${posts.map(post => `<li>${post.title}</li>`).join('')}
                    </ul>
                </body>
            </html>
        `;

        // Send the HTML response
        res.send(html);
    } catch (error) {
        // Handle errors
        console.error('Error fetching data:', error);
        res.status(500).send('Error fetching data');
    }
});

// Start the Express server
app.listen(port, () => {
    console.log(`Server is running on http://localhost:${port}`);
});
```

In this example:

1. We import the required libraries, `express` for creating the server and `axios` for making HTTP requests.
2. We create an Express application and define a route to handle the root URL (`/`).
3. Inside the route handler, we make a POST request to the GraphQL endpoint using `axios`, passing the GraphQL query as a string in the request body.
4. We extract the data from the response and use it to dynamically generate HTML markup.
5. We render the HTML response using `res.send()`.
6. We handle any errors that occur during the process and send an appropriate error response if needed.
7. Finally, we start the Express server listening on port 3000.

