import javax.swing.*;
import javax.swing.tree.DefaultMutableTreeNode;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.File;

public class FileExplorer extends JFrame {

    private JTree fileTree;
    private DefaultMutableTreeNode rootNode;

    public FileExplorer() {
        setTitle("File Explorer");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(400, 300);
        setLocationRelativeTo(null);

        // Create the root node for the file tree
        rootNode = new DefaultMutableTreeNode("Files");

        // Create the JTree with the root node
        fileTree = new JTree(rootNode);
        JScrollPane scrollPane = new JScrollPane(fileTree);
        getContentPane().add(scrollPane, BorderLayout.CENTER);

        JButton btnBrowse = new JButton("Browse");
        btnBrowse.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                JFileChooser fileChooser = new JFileChooser();
                fileChooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);

                int option = fileChooser.showOpenDialog(FileExplorer.this);
                if (option == JFileChooser.APPROVE_OPTION) {
                    File selectedFolder = fileChooser.getSelectedFile();
                    listFiles(selectedFolder);
                }
            }
        });

        getContentPane().add(btnBrowse, BorderLayout.NORTH);

        setVisible(true);
    }

    private void listFiles(File folder) {
        rootNode.removeAllChildren();
        addFilesToTree(folder, rootNode);
        fileTree.updateUI();
    }

    private void addFilesToTree(File folder, DefaultMutableTreeNode parent) {
        File[] files = folder.listFiles();
        if (files != null) {
            for (File file : files) {
                DefaultMutableTreeNode node = new DefaultMutableTreeNode(file.getName());
                parent.add(node);

                if (file.isDirectory()) {
                    addFilesToTree(file, node);
                }
            }
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new FileExplorer();
            }
        });
    }
}
```

