import { fetchWords } from './wordsSlice';

function YourComponent() {
  const dispatch = useDispatch();
  const { data, loading, error } = useSelector((state) => state.words);

  // Trigger the fetchWords action
  useEffect(() => {
    dispatch(fetchWords({ page: 1, pageSize: 10 }));
  }, [dispatch]);

  if (loading) {
    return <p>Loading...</p>;
  }

  if (error) {
    return <p>Error: {error}</p>;
  }

  return (
    <div>
      {data.map((word) => (
        <p key={word.id}>{word.word}</p>
      ))}
    </div>
  );
}

export default YourComponent;
```

This is a basic setup. Adjust it according to your application structure and requirements. The data will be available in the Redux store under the `words` slice, and you can access it in your components using the `useSelector` hook.

