```java
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.stereotype.Component;

import java.io.BufferedReader;
import java.io.FileReader;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@SpringBootApplication
public class ImportDataApplication {

    public static void main(String[] args) {
        SpringApplication.run(ImportDataApplication.class, args);
    }
}

@Component
class DataImporter implements CommandLineRunner {

    private final MongoTemplate mongoTemplate;

    public DataImporter(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @Override
    public void run(String... args) throws Exception {
        // Specify the path to your file
        String filePath = "/path/to/your/file.txt"; // Replace with the actual path to your file

        // Process the file and insert data into MongoDB
        processFile(filePath);
    }

    private void processFile(String filePath) {
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                insertData(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void insertData(String line) {
        Pattern pattern = Pattern.compile("INSERT INTO `t_word` VALUES \\((\\d+),'([^']+)','([^']+)','([^']+)','([^']+)','([^']+)','([^']+)','([^']+)');");

        Matcher matcher = pattern.matcher(line);

        if (matcher.matches()) {
            int id = Integer.parseInt(matcher.group(1));
            String uniqueName = matcher.group(2);
            String word = matcher.group(3);
            String type = matcher.group(4);
            String details = matcher.group(5);
            String createdOn = matcher.group(6);
            String updatedOn = matcher.group(7);
            String lastRead = matcher.group(8);

            // Create and save a Word entity (assuming Word is a MongoDB document entity)
            Word newWord = new Word(id, uniqueName, word, type, details, createdOn, updatedOn, lastRead);
            mongoTemplate.save(newWord);
            System.out.println("Document inserted: " + newWord);
        } else {
            System.out.println("Line does not match: " + line);
        }
    }
}
```

In this example:

- `ImportDataApplication` is the main Spring Boot application class.
- `DataImporter` is a component that implements `CommandLineRunner` to execute code when the application starts.
- The `processFile` method reads each line from the file, and `insertData` processes each line and inserts data into MongoDB using Spring Data MongoDB.

