```javascript
const mysql = require('mysql');
const mongoose = require('mongoose');

// MySQL configuration
const mysqlConfig = {
  host: 'localhost',
  user: 'your_mysql_user',
  password: 'your_mysql_password',
  database: 'your_mysql_database',
};

// MongoDB configuration
const mongoURI = 'mongodb://localhost:27017/your_mongo_database';

// Mongoose schema
const wordSchema = new mongoose.Schema({
  id: Number,
  unique_name: String,
  word: String,
  type: String,
  details: String,
  created_on: Date,
  updated_on: Date,
  last_read: Date,
});

const Word = mongoose.model('Word', wordSchema);

// Create MySQL connection
const mysqlConnection = mysql.createConnection(mysqlConfig);

// Connect to MySQL
mysqlConnection.connect((err) => {
  if (err) {
    console.error('Error connecting to MySQL:', err);
    return;
  }

  console.log('Connected to MySQL');

  // Paginate the select query to fetch 100 rows at a time
  const pageSize = 100;
  let offset = 0;

  function fetchNextPage() {
    const selectQuery = `SELECT * FROM t_word LIMIT ${offset}, ${pageSize}`;

    // Execute the select query
    mysqlConnection.query(selectQuery, (selectError, results) => {
      if (selectError) {
        console.error('Error executing select query:', selectError);
        mysqlConnection.end();
        return;
      }

      if (results.length === 0) {
        // No more data, close MySQL connection
        mysqlConnection.end();
        // Close MongoDB connection after all documents are inserted
        mongoose.connection.close();
        return;
      }

      // Connect to MongoDB
      mongoose.connect(mongoURI, { useNewUrlParser: true, useUnifiedTopology: true });

      // Insert data into MongoDB
      results.forEach((row) => {
        const newWord = new Word({
          id: row.id,
          unique_name: row.unique_name,
          word: row.word,
          type: row.type,
          details: row.details,
          created_on: row.created_on,
          updated_on: row.updated_on,
          last_read: row.last_read,
        });

        newWord.save((mongoError) => {
          if (mongoError) {
            console.error('Error inserting document into MongoDB:', mongoError);
          } else {
            console.log('Document inserted into MongoDB:', newWord);
          }
        });
      });

      // Fetch the next page
      offset += pageSize;
      fetchNextPage();
    });
  }

  // Start fetching the first page
  fetchNextPage();
});
```

In this script:

- The `pageSize` variable determines the number of rows to fetch in one query (set to 100).
- The `offset` variable keeps track of the starting position for each page.
- The `fetchNextPage` function fetches the next page of data and continues until there is no more data to fetch.

Adjust the placeholders and connection details as needed for your specific MySQL and MongoDB configurations.

