5. Create GraphQL resolvers:

```java
import com.coxautodev.graphql.tools.GraphQLQueryResolver;
import com.coxautodev.graphql.tools.GraphQLMutationResolver;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;

@Component
public class TaskCategoryResolver implements GraphQLQueryResolver, GraphQLMutationResolver {
    @Autowired
    private TaskCategoryRepository taskCategoryRepository;

    public List<TaskCategory> taskCategories() {
        return taskCategoryRepository.findAll();
    }

    public TaskCategory taskCategory(Long id) {
        return taskCategoryRepository.findById(id).orElse(null);
    }

    public TaskCategory createTaskCategory(TaskCategoryInput input) {
        TaskCategory taskCategory = new TaskCategory();
        taskCategory.setName(input.getName());
        taskCategory.setDescription(input.getDescription());
        taskCategory.setActive(input.getActive());
        taskCategory.setCreatedDate(new Date());
        return taskCategoryRepository.save(taskCategory);
    }

    public TaskCategory updateTaskCategory(Long id, TaskCategoryInput input) {
        Optional<TaskCategory> optionalTaskCategory = taskCategoryRepository.findById(id);
        if (optionalTaskCategory.isPresent()) {
            TaskCategory taskCategory = optionalTaskCategory.get();
            taskCategory.setName(input.getName());
            taskCategory.setDescription(input.getDescription());
            taskCategory.setActive(input.getActive());
            return taskCategoryRepository.save(taskCategory);
        }
        return null;
    }

    public Boolean deleteTaskCategory(Long id) {
        taskCategoryRepository.deleteById(id);
        return true;
    }
}
```

