import java.io.IOException;

@Configuration
public class GraphQLConfig {
    @Bean
    public GraphQL graphQL() throws IOException {
        Resource schemaResource = new ClassPathResource("graphql/schema.graphqls");
        TypeDefinitionRegistry typeRegistry = new SchemaParser().parse(schemaResource.getInputStream());
        RuntimeWiring wiring = buildRuntimeWiring();
        GraphQLSchema schema = new SchemaGenerator().makeExecutableSchema(typeRegistry, wiring);
        return GraphQL.newGraphQL(schema).build();
    }

    private RuntimeWiring buildRuntimeWiring() {
        // Define your resolvers here if needed
        return RuntimeWiring.newRuntimeWiring().build();
    }
}
