        headers.add("Authorization", "Bearer YOUR_ACCESS_TOKEN"); // Example of adding an Authorization header

        // Set up the HTTP entity with headers (can be used for GET, POST, PUT, etc.)
        HttpEntity<String> requestEntity = new HttpEntity<>(headers);

        // Perform the GET request with headers
