                    .attr("height", height)
                    .style("display", styles.chart.display)
                    .style("margin-right", styles.chart.marginRight);

                const x = d3.scaleBand()
                    .domain(data.map(d => d.name))
                    .range([margin.left, width - margin.right])
                    .padding(0.1);

                const y = d3.scaleLinear()
                    .domain([0, d3.max(data, d => d.daysPresent)]).nice()
                    .range([height - margin.bottom, margin.top]);

                svg.append("g")
                    .attr("transform", `translate(0,${height - margin.bottom})`)
                    .call(d3.axisBottom(x));

                svg.append("g")
                    .attr("transform", `translate(${margin.left},0)`)
                    .call(d3.axisLeft(y));

                const line = d3.line()
                    .x(d => x(d.name) + x.bandwidth() / 2)
                    .y(d => y(d.daysPresent));

                svg.append("path")
                    .datum(data)
                    .attr("fill", "none")
                    .attr("stroke", "steelblue")
                    .attr("stroke-width", 1.5)
                    .attr("d", line);

                svg.selectAll(".dot")
                    .data(data)
                    .enter().append("circle")
                    .attr("class", "dot")
                    .attr("cx", d => x(d.name) + x.bandwidth() / 2)
                    .attr("cy", d => y(d.daysPresent))
                    .attr("r", 3)
                    .attr("fill", "steelblue");
            };

            // Render charts
            const renderCharts = () => {
                renderBarChart(attendanceData, "#bar-chart-container");
                renderPieChart(attendanceData, "#pie-chart-container");
                renderLineChart(attendanceData, "#line-chart-container");
            };

            renderCharts();
        })();
    </script>
</body>
</html>
```

