                    .domain([0, d3.max(data, d => d.daysPresent)]).nice()
                    .range([height - margin.bottom, margin.top]);

                svg.append("g")
                    .attr("transform", `translate(0,${height - margin.bottom})`)
                    .call(d3.axisBottom(x));

                svg.append("g")
                    .attr("transform", `translate(${margin.left},0)`)
                    .call(d3.axisLeft(y));

                const line = d3.line()
                    .x(d => x(d.name) + x.bandwidth() / 2)
                    .y(d => y(d.daysPresent));

                svg.append("path")
                    .datum(data)
                    .attr("fill", "none")
                    .attr("stroke", "steelblue")
                    .attr("stroke-width", 1.5)
                    .attr("d", line);

                svg.selectAll(".dot")
                    .data(data)
                    .enter().append("circle")
                    .attr("class", "dot")
                    .attr("cx", d => x(d.name) + x.bandwidth() / 2)
                    .attr("cy", d => y(d.daysPresent))
                    .attr("r", 3)
                    .attr("fill", "steelblue");
            };

            // Render charts
            renderBarChart(attendanceData, "#bar-chart-container");
            renderPieChart(attendanceData, "#pie-chart-container");
            renderLineChart(attendanceData, "#line-chart-container");
        })();
    </script>
</body>
</html>
```

### Explanation:

1. **Style Configuration JSON**: A `styles` object defines the styles for different chart elements.
2. **Rendering Functions**: Each rendering function (`renderBarChart`, `renderPieChart`, `renderLineChart`) applies the styles from the `styles` object using D3.js's `style` method.
3. **Appending to Specific Divs**: Each chart is appended to its designated container div, and the styles are applied according to the configuration in the JSON object.

This approach centralizes the styling in one JSON object, making it easier to manage and update the styles as needed.

