     * Adds a new HTML element with specified attributes and returns it.
     * @param {Object} params - Parameters for creating the element.
     * @param {string} params.elementType - The type of the element to create (e.g., 'div', 'input').
     * @param {boolean} params.addToBody - Whether to add the element directly to the body.
     * @param {string} [params.parentElementId] - The ID of the parent element to add the new element to.
     * @param {Object} [params.style] - An object containing the styles to apply to the element.
     * @param {string} [params.innerText] - The inner text or placeholder text for the element.
     * @param {Function} [params.onClick] - A callback function to attach to the element's click event.
     * @param {Array} [params.options] - An array of options for the select element.
     * @returns {Promise<HTMLElement>} A promise that resolves to the created HTML element.
     */
    const addElementWithPromise = ({
        elementType, addToBody, parentElementId, style, innerText, onClick, options
    } = {
        elementType: "",
        addToBody: false,
        parentElementId: "",
        style: {},
        innerText: "",
        onClick: () => { },
        options: [],
    }) => {
        return new Promise((resolve, reject) => {
            const { isValid, error, parentElement } = validateParams({ elementType, addToBody, parentElementId });

            if (!isValid) {
                reject(new Error(error));
                return;
            }

            const id = `element-${Math.random().toString(36).substr(2, 9)}`;
            let htmlElementToBeCreated;

            switch (elementType.trim().toLowerCase()) {
                case "div":
                case "input":
                case "button":
                case "span":
                case "h1":
                case "h2":
                case "h3":
                case "p":
                case "ul":
                case "li":
                case "header":
                case "footer":
                case "section":
                case "article":
                    htmlElementToBeCreated = createElement(elementType, { id }, '', style, { click: onClick });
                    if (elementType === "input") htmlElementToBeCreated.placeholder = innerText || id;
                    if (elementType === "a") htmlElementToBeCreated.href = '#';
                    break;
                case "select":
                    htmlElementToBeCreated = createElement(elementType, { id }, '', style, { change: onClick });
                    if (options && Array.isArray(options)) {
                        options.forEach(optionData => {
                            const option = createElement("option", { value: optionData.value }, optionData.label);
                            htmlElementToBeCreated.appendChild(option);
                        });
                    }
                    break;
                case "img":
                    htmlElementToBeCreated = createElement(elementType, { id, src: innerText || '' }, '', style, { click: onClick });
                    break;
                default:
                    reject(new Error(`Error occurred while loading elementType '${elementType}'`));
                    return;
            }

            if (parentElement) {
                parentElement.appendChild(htmlElementToBeCreated);
            } else {
                document.body.appendChild(htmlElementToBeCreated);
            }
            resolve(htmlElementToBeCreated);
        });
    };

    return { addElementWithPromise };
})();

export default elementAdderUtility;
```

In this combined script, the `elementAdderUtility` module uses utility functions from `ElementCreatorUtil.js` to create elements with specified attributes, styles, and event listeners. It also validates the parameters and applies common attributes to the created elements. This approach consolidates the functionality into a single module for easier management and usage.

Dependency injection (DI) is a design pattern used to achieve Inversion of Control (IoC) between classes and their dependencies. It allows a class to receive its dependencies from an external source rather than creating them itself. This can improve code modularity, testing, and maintenance.

Here's a simple example of dependency injection in JavaScript:

1. **Without Dependency Injection:**

```javascript
class Logger {
  log(message) {
    console.log(message);
  }
}

class UserService {
  constructor() {
    this.logger = new Logger();
  }

  getUser() {
    this.logger.log('Getting user');
    // Simulated user fetch
    return { id: 1, name: 'John Doe' };
  }
}

const userService = new UserService();
const user = userService.getUser();
console.log(user);
```

In this example, `UserService` creates its own `Logger` instance, making it harder to replace or mock the `Logger` for testing.

2. **With Dependency Injection:**

```javascript
class Logger {
  log(message) {
    console.log(message);
  }
}

class UserService {
  constructor(logger) {
    this.logger = logger;
  }

  getUser() {
    this.logger.log('Getting user');
    // Simulated user fetch
    return { id: 1, name: 'John Doe' };
  }
}

// Create the logger instance
const logger = new Logger();

// Inject the logger instance into the UserService
const userService = new UserService(logger);

const user = userService.getUser();
console.log(user);

// Now we can easily replace the logger for testing
class MockLogger {
  log(message) {
    console.log(`Mock log: ${message}`);
  }
}

const mockLogger = new MockLogger();
const userServiceWithMockLogger = new UserService(mockLogger);
const mockUser = userServiceWithMockLogger.getUser();
console.log(mockUser);
```

In this example, `UserService` receives a `Logger` instance via its constructor. This allows us to inject a different logger, such as `MockLogger`, making it easier to test `UserService`.

### Dependency Injection in a More Complex Scenario:

For a more complex application, you might use a DI container to manage dependencies. Below is a simple example of a basic DI container:

```javascript
class DIContainer {
  constructor() {
    this.services = {};
  }

  register(name, dependency) {
    this.services[name] = dependency;
  }

  get(name) {
    return this.services[name];
  }
}

class Logger {
  log(message) {
    console.log(message);
  }
}

class UserService {
  constructor(logger) {
    this.logger = logger;
  }

  getUser() {
    this.logger.log('Getting user');
    // Simulated user fetch
    return { id: 1, name: 'John Doe' };
  }
}

// Create DI container
const container = new DIContainer();

// Register dependencies
container.register('logger', new Logger());
container.register('userService', new UserService(container.get('logger')));

// Resolve dependencies
const userService = container.get('userService');
const user = userService.getUser();
console.log(user);
```

In this example, `DIContainer` is used to register and resolve dependencies. This approach centralizes the creation and management of dependencies, making the codebase more modular and testable.

Sure, here’s how you can update the `script.js` file to load a script based on the selected option's value when the selection changes:

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Create select element
    const select = document.createElement('select');
    select.id = 'mySelect';

    // Define options
    const options = [
        { value: 'script1.js', label: 'Initial Script' },
        { value: 'script2.js', label: 'Option 2' },
        { value: 'script3.js', label: 'Option 3' }
    ];

    // Add options to the select element
    options.forEach(optionData => {
        const option = document.createElement('option');
        option.value = optionData.value;
        option.innerText = optionData.label;
        select.appendChild(option);
    });

    // Create a div to display selected value
    const displayDiv = document.createElement('div');
    displayDiv.id = 'display';
    displayDiv.innerText = 'Selected value will be displayed here';

    // Add event listener to select element
    select.addEventListener('change', function() {
        const selectedScript = select.value;
        displayDiv.innerText = `Selected: ${selectedScript}`;
        loadScript(selectedScript).then(
            script => alert(`${script.src} is loaded!`),
            error => alert(`Error: ${error.message}`)
        ).then(script => alert('Another handler...'));
    });

    // Append elements to the body
    document.body.appendChild(select);
    document.body.appendChild(displayDiv);

    // Function to load a script
    function loadScript(src) {
        return new Promise(function(resolve, reject) {
            const script = document.createElement('script');
            script.src = src;
            script.onload = () => resolve(script);
            script.onerror = () => reject(new Error(`Script load error for ${src}`));
            document.head.append(script);
        });
    }
});
```

And the `index.html` file remains the same:

