        info: 'color: white; background-color: blue; padding: 5px; margin: 20px; border-radius: 3px; display: block;',
        success: 'color: white; background-color: green; padding: 5px; margin: 20px; border-radius: 3px; display: block;'
    };

    const createMessageSpan = (type, text) => {
        const span = document.createElement('span');
        span.style.cssText = styles[type];
        span.textContent = text;
        return span;
    };

    const container = document.createElement('div');
    messages.forEach(msg => {
        const messageSpan = createMessageSpan(msg.type, msg.text);
        container.appendChild(messageSpan);
    });

    document.body.appendChild(container);
})();
```

