// Helper function to simulate random API failures
const simulateApiCall = (response, failRate = 0.2) => {
  return new Promise((resolve, reject) => {
    if (Math.random() < failRate) {
      reject(new Error("Simulated API failure"));
    } else {
      resolve(response);
    }
  });
};

