    value: value,
    label: key
}));

const SelectComponent = () => {
    const [selectedValue, setSelectedValue] = useState('');

    const handleChange = (event) => {
        setSelectedValue(event.target.value);
        console.log(`Selected value: ${event.target.value}`);
    };

    return (
        <div>
            <label htmlFor="conversationSelect">Select a Conversation:</label>
            <select id="conversationSelect" onChange={handleChange} value={selectedValue}>
                <option value="" disabled>Select a conversation</option>
                {mappedArray.map((item, index) => (
                    <option key={index} value={item.value}>
                        {item.label}
                    </option>
                ))}
            </select>
            {selectedValue && (
                <div>
                    <p>Selected Conversation: {selectedValue}</p>
                </div>
            )}
        </div>
    );
};

export default SelectComponent;
```

### Explanation

1. **State Management with `useState`**:
   - `useState` is used to manage the state of the selected value in the select dropdown. The initial state is an empty string (`''`).

2. **`handleChange` Function**:
   - This function is called whenever the selected value changes. It updates the state with the new selected value and logs the value to the console.

3. **`onChange` Attribute in `<select>`**:
   - The `onChange` attribute is set to the `handleChange` function. This ensures that the `handleChange` function is called whenever the user selects a new option.

4. **Selected Value Display**:
   - If a value is selected, it is displayed in a paragraph below the select dropdown.

### Usage

You can use this component in your main application file in the same way as before:

```javascript
import React from 'react';
import ReactDOM from 'react-dom';
import SelectComponent from './SelectComponent';

const App = () => {
    return (
        <div>
            <h1>Conversation Selector</h1>
            <SelectComponent />
        </div>
    );
};

ReactDOM.render(<App />, document.getElementById('root'));
```

This code will render a select dropdown with an `onChange` handler that logs and displays the selected conversation value.

To make debugging easier by being able to trace errors back to the original source files, you can enable source maps in your Webpack configuration. Source maps provide a way to map the code within a compressed file back to its original source file, allowing you to debug the original source code in your browser.

Here's how you can enable source maps in your Webpack configuration:

1. **Update your `webpack.config.js` to include source maps:**

```javascript
const path = require('path');
const glob = require('glob');

// Function to get all JavaScript files in a directory and its subdirectories
function getJavaScriptFiles(dir) {
  const files = glob.sync(`${dir}/**/*.js`);
  return files.reduce((entries, file) => {
    const entryName = path.relative(dir, file).replace(/\\/g, '/').replace(/\.js$/, '');
    entries[entryName] = path.resolve(__dirname, file);
    return entries;
  }, {});
}

module.exports = {
  entry: getJavaScriptFiles('./src/scripts'), // Dynamically get all JS files in src/js/lib and its subdirectories
  output: {
    filename: '[name].js', // Dynamically name output bundles based on entry keys
    path: path.resolve(__dirname, 'dist'),
    publicPath: '/dist/'
  },
  module: {
    rules: [
      {
        test: /\.js$/,
        exclude: /node_modules/,
        use: {
          loader: 'babel-loader',
        },
      },
    ],
  },
  mode: 'development',
  devtool: 'source-map', // Add this line to enable source maps
  devServer: {
    static: {
      directory: path.join(__dirname, 'public'),
    },
    compress: true,
    port: 6060,
    open: true,
    hot: true,
  },
};
```

2. **Install the necessary Webpack and Babel dependencies if not already installed:**

```bash
npm install --save-dev webpack webpack-cli webpack-dev-server babel-loader @babel/core @babel/preset-env source-map-loader
```

3. **Configure Babel to include source maps (optional but recommended for better source maps):**

Create or update your `.babelrc` or `babel.config.js` file to include source maps:

```json
{
  "presets": ["@babel/preset-env"],
  "sourceMaps": true
}
```

Now, when you run your development server with `npm run start-dev`, Webpack will generate source maps. In the browser's developer tools, you should be able to see and debug the original source files instead of the transpiled ones.

**Note:** Using source maps may slightly increase the build time and size of the output files, but it greatly enhances the debugging experience. For production builds, you can choose a different source map style or disable them entirely to optimize performance.

