    .then((val) => checkDivisibility(val / 2, 3, "After division:"))
    .then((val) => logValue(val - 6, "After subtraction:"))
    .then((val) => {
      console.log(val, val === value);
      success = true;
    })
    .catch((err) => console.error(err))
    .finally(() => {
