import { applyStyles, getStylesForType } from './styles.js';
import { validConfig, registerLoggingConfig } from './validation.js';

class LoggerUtility {
    constructor() {
        this.registeredElement = null;
    }

    registerLoggingConfig(element, elementId) {
        if (element) {
            this.registeredElement = element;
        } else if (elementId) {
            const el = document.getElementById(elementId);
            if (el) {
                this.registeredElement = el;
            }
        }
    }

    createMessageSpan(type = '', logMessage = '') {
        const span = document.createElement('span');
        applyStyles(span, getStylesForType(type));
        span.innerHTML = `<b>[${type.toUpperCase()}]: </b>[${new Date().toString()}]: ${logMessage}`;
        return span;
    }

    appendInnerHtmlToElement(message, logLevel = 'info') {
        if (!validConfig(this.registeredElement)) {
            return;
        }
        const messageSpan = this.createMessageSpan(logLevel, message);
        this.registeredElement.appendChild(messageSpan);
    }

    resetInnerHtmlToElement() {
        if (!validConfig(this.registeredElement)) {
            return;
        }
        this.registeredElement.innerHTML = `<b>Logs to be displayed:-</b>`;
    }

    logToConsole(message, logLevel = 'info') {
        if (logLevel && message) {
            const logFunction = console[logLevel] || console.log;
            logFunction(`[${logLevel.trim().toUpperCase()}]: [${new Date()}]: ${message}`);
        }
    }

    log(logLevel = 'info', ...message) {
        const validLogLevels = ['info', 'warn', 'success', 'error', 'debug', 'trace'];
        if (!validLogLevels.includes(logLevel.trim().toLowerCase())) {
            console.log(`Invalid/Unknown Log Level: '${logLevel}'. Unable to log message.`);
            return;
        } else if (!message) {
            console.log(`Invalid Message: '${message}'. Unable to log message.`);
            return;
        }

        this.logToConsole(message, logLevel);
        this.appendInnerHtmlToElement(message, logLevel);
    }

    info(...message) { this.log('info', message); }
    warning(...message) { this.log('warn', message); }
    success(...message) { this.log('success', message); }
    error(...message) { this.log('error', message); }
    trace(...message) { this.log('trace', message); }
    debug(...message) { this.log('debug', message); }
    reset() { this.resetInnerHtmlToElement(); }
}

const loggerUtility = new LoggerUtility();
export default loggerUtility;

