import employeeData from "./employeeData";

/**
 * Experimental @global @constant SKIP_SIMULATION
 * 
 * If true, all promises will only show success results
 * 
*/
const SKIP_SIMULATION = false;

const DEFAULT_THRESHOLD = 0.8;
const MAX_TIMEOUT_IN_MS = 10000;
const MIN_TIMEOUT_IN_MS = 100;
const DEFAULT_TIMEOUT_IN_MS = 1000;

const validateSimulationAndTimeout = ({
    timeoutInMS,
    threshold = DEFAULT_THRESHOLD,
}) => {

    const calculatedTimeOut =
        timeoutInMS &&
            !isNaN(timeoutInMS) &&
            timeoutInMS <= MAX_TIMEOUT_IN_MS &&
            timeoutInMS >= MIN_TIMEOUT_IN_MS
            ? timeoutInMS
            : DEFAULT_TIMEOUT_IN_MS;

    if (SKIP_SIMULATION && SKIP_SIMULATION===true) {
        return {
            randomNumber: 0.5,
            result: true,
            calculatedTimeOut,
        }
    }

    const randomNumber = Math.random();

    return {
        randomNumber,
        result: randomNumber < threshold,
        calculatedTimeOut,
    };
};

