/**
 * Renders a bar chart.
 * @param {Object[]} data - The data to render.
 * @param {string} container - The container to render the chart in.
 */
const renderBarChart = (data, container) => {
    const width = 500;
    const height = 300;
    const margin = { top: 20, right: 30, bottom: 40, left: 40 };

    const svg = d3
        .select(container)
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .style("display", styles.chart.display)
        .style("margin-right", styles.chart.marginRight);

    const x = d3
        .scaleBand()
        .domain(data.map((d) => d.name))
        .range([margin.left, width - margin.right])
        .padding(0.1);

    const y = d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.daysPresent)])
        .nice()
        .range([height - margin.bottom, margin.top]);

    svg
        .append("g")
        .attr("transform", `translate(0,${height - margin.bottom})`)
        .call(d3.axisBottom(x));

    svg
        .append("g")
        .attr("transform", `translate(${margin.left},0)`)
        .call(d3.axisLeft(y));

    svg
        .selectAll(".bar")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "bar")
        .attr("x", (d) => x(d.name))
        .attr("y", (d) => y(d.daysPresent))
        .attr("height", (d) => y(0) - y(d.daysPresent))
        .attr("width", x.bandwidth())
        .style("fill", styles.bar.fill);
};

/**
 * Renders a pie chart.
 * @param {Object[]} data - The data to render.
 * @param {string} container - The container to render the chart in.
