                reject(new Error(`[Ambiguous situation]: Both addToBody : '${addToBody}' and parentElementId : '${parentElementId}' {A non-empty value} should not be provided.`));
                return;
            } else if (!addToBody && (!parentElementId || parentElementId.trim().length < 1)) {
                reject(new Error(`Unable to create element with addToBody:'${addToBody}' and parentElementId : '${parentElementId}' {An invalid value} is provided simulaneously.`));
                return;
            } else if (!addToBody && parentElementId) {
                parentElement = document.getElementById(parentElementId);
                if (!parentElement) {
                    reject(new Error(`Parent Element with ID '${parentElementId}' does not exist.`));
                    return;
                }
            }

            let htmlElementToBeCreated = null;
            const id = generateString({ length: 20, prefix: elementType });
            switch (elementType.trim().toLowerCase()) {
                case "div":
                case "input":
                case "button":
                case "span":
                case "h1":
                case "h2":
                case "h3":
                    htmlElementToBeCreated = document.createElement(elementType);
                    htmlElementToBeCreated.id = id;
                    applyStyles(htmlElementToBeCreated, style || getDefaultStyle(elementType));
                    htmlElementToBeCreated.innerText = innerText || id;
                    if (elementType === "input") {
                        htmlElementToBeCreated.placeholder = innerText || id;
                    }
                    if (onClick) {
                        htmlElementToBeCreated.addEventListener("click", onClick);
                    }
                    if (addToBody) {
                        document.body.append(htmlElementToBeCreated);
                    } else {
                        parentElement.appendChild(htmlElementToBeCreated);
                    }
                    resolve(htmlElementToBeCreated);
                    break;
                case "select":
                    htmlElementToBeCreated = document.createElement(elementType);
                    htmlElementToBeCreated.id = id;
                    applyStyles(htmlElementToBeCreated, style || getDefaultStyle(elementType));
                    if (options && Array.isArray(options)) {
                        options.forEach(optionData => {
                            const option = document.createElement("option");
                            option.value = optionData.value;
                            option.innerText = optionData.label;
                            htmlElementToBeCreated.appendChild(option);
                        });
                    }
                    if (onClick) {
                        htmlElementToBeCreated.addEventListener("change", onClick);
                    }
                    if (addToBody) {
                        document.body.append(htmlElementToBeCreated);
                    } else {
                        parentElement.appendChild(htmlElementToBeCreated);
                    }
                    resolve(htmlElementToBeCreated);
                    break;
                default:
                    reject(new Error(`Error occured while loading elementType '${elementType}'`));
                    break;
            }
        });
    };

    return {
        addElementWithPromise,
    };
})();

export default elementAdderUtility;
```

### Explanation:

1. **getDefaultStyle Function**:
    - This function returns a default style object for each element type.
    - If an element type is not specified, it returns an empty object.

2. **applyStyles Function**:
    - This function applies styles to an element if provided. If no styles are provided, it applies default styles using the `getDefaultStyle` function.

3. **addElementWithPromise Function**:
    - In the `switch` statement, each case applies the provided styles or the default styles using the `applyStyles` function.
    - Added `options` for the `select` element to handle the creation of option elements.

Now, the `elementAdderUtility` will apply default styles to elements if the user does not provide any styles.

When adding a `<div>` element (or any HTML element) programmatically to the body using `document.body.append(htmlElementToBeCreated);`, the `onload` and `onerror` events are not applicable because these events are specific to elements like `<img>`, `<script>`, `<iframe>`, etc., which load external resources.

For a `<div>`, you typically work with DOMContentLoaded or other general event listeners to manipulate the DOM after it's loaded. Here is how you can work with such scenarios:

1. **DOMContentLoaded**: To ensure your script runs after the DOM is fully loaded.
2. **MutationObserver**: To observe changes to the DOM tree.

Here's an example using both approaches:

### Using `DOMContentLoaded`
```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Create a new div element
    const newDiv = document.createElement('div');
    newDiv.id = 'some-unique-id';
    newDiv.innerText = 'This is a new div.';

    // Append the div to the body
    document.body.appendChild(newDiv);

    // Set styles on the new div
    newDiv.style.fontSize = '20px';
    newDiv.style.lineHeight = '400px';
    newDiv.style.textAlign = 'center';

    // Handle any additional actions after the div is added
    console.log('New div added to the body.');
});
```

### Using `MutationObserver`
```javascript
// Create a MutationObserver to observe changes in the body
const observer = new MutationObserver((mutationsList, observer) => {
    for (let mutation of mutationsList) {
        if (mutation.type === 'childList') {
            mutation.addedNodes.forEach(node => {
                if (node.id === 'some-unique-id') {
                    // Handle actions when the specific div is added
                    console.log('New div with id "some-unique-id" added.');
                }
            });
        }
    }
});

// Start observing the body for added child nodes
observer.observe(document.body, { childList: true });

// Function to add a new div
function addNewDiv() {
    // Create a new div element
    const newDiv = document.createElement('div');
    newDiv.id = 'some-unique-id';
    newDiv.innerText = 'This is a new div.';

    // Append the div to the body
    document.body.appendChild(newDiv);

    // Set styles on the new div
    newDiv.style.fontSize = '20px';
    newDiv.style.lineHeight = '400px';
    newDiv.style.textAlign = 'center';
}

// Add the new div
addNewDiv();
```

In the second example, `MutationObserver` is used to observe changes to the DOM and detect when a new element is added. This is more advanced and can be useful for dynamically changing pages or when you need to respond to elements being added asynchronously.

