### 4. Grouping Objects by a Property

```javascript
const people = [
    { name: 'Alice', age: 21 },
    { name: 'Bob', age: 21 },
    { name: 'Charlie', age: 23 },
    { name: 'David', age: 23 },
    { name: 'Eve', age: 22 }
];

const groupedByAge = people.reduce((accumulator, currentValue) => {
    const age = currentValue.age;
    if (!accumulator[age]) {
