    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Remove All Elements</title>
</head>
<body>
    <div id="myDiv">
        <p>Child 1</p>
        <p>Child 2</p>
        <p>Child 3</p>
    </div>
    <button onclick="removeChildrenMethod1()">Remove All (Method 1)</button>
    <button onclick="removeChildrenMethod2()">Remove All (Method 2)</button>
    <button onclick="removeChildrenMethod3()">Remove All (Method 3)</button>

    <script>
        function removeChildrenMethod1() {
            const divElement = document.getElementById('myDiv');
            divElement.innerHTML = '';
        }

        function removeChildrenMethod2() {
            const divElement = document.getElementById('myDiv');
            while (divElement.firstChild) {
                divElement.removeChild(divElement.firstChild);
            }
        }

        function removeChildrenMethod3() {
            const divElement = document.getElementById('myDiv');
            divElement.replaceChildren();
        }
    </script>
</body>
</html>
```
