You can dynamically style the `removeElementButtonEl` button to be visible only when `customComponentsIdList` is not empty (truthy) by using JavaScript to check the array's length and set the button's display style accordingly.

Here's the complete code, including the creation of the button, adding the `removeLastComponent` function, and dynamically adjusting the button's visibility:

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const customComponentsIdList = [];

    // Create the remove button
    const removeElementButtonEl = document.createElement("button");
    removeElementButtonEl.textContent = "Remove Last Component";
    document.body.appendChild(removeElementButtonEl);

    // Style the button initially (hidden)
    removeElementButtonEl.style.display = 'none';

    // Function to add a new component ID
    function addComponentId(id) {
        customComponentsIdList.push(id);
        updateButtonVisibility();
    }

    // Function to remove the last added component ID
    function removeLastComponent() {
        const lastElementId = customComponentsIdList.pop(); // Remove the last element ID from the array
        if (lastElementId) {
            const element = document.getElementById(lastElementId);
            if (element) {
                element.parentElement.removeChild(element);
                console.log(`Element with ID ${lastElementId} has been removed.`);
            } else {
                console.log(`Element with ID ${lastElementId} does not exist in the DOM.`);
            }
        } else {
            console.log('No elements in customComponentsIdList to remove.');
        }
        updateButtonVisibility();
    }

    // Function to update the button visibility based on the array length
    function updateButtonVisibility() {
        if (customComponentsIdList.length > 0) {
            removeElementButtonEl.style.display = 'inline-block';
        } else {
            removeElementButtonEl.style.display = 'none';
        }
    }

    // Add click event listener to the button
    removeElementButtonEl.addEventListener('click', removeLastComponent);

    // Example usage
