Here's how you might conceptualize such a TypeScript definition:

```typescript
// Define ElementCreationOptions interface for options parameter
interface ElementCreationOptions {
    id?: string;
    className?: string;
    attributes?: { [key: string]: string };
    style?: Partial<CSSStyleDeclaration>;
    eventListeners?: { [key: string]: EventListenerOrEventListenerObject };
    textContent?: string;
    // Add more options as needed
}

// Extend Document interface with a custom method signature
interface Document {
    createElement<K extends keyof HTMLElementTagNameMap>(
        tagName: K,
        options?: ElementCreationOptions
    ): HTMLElementTagNameMap[K];
}

// Implementation example
const createElementWithOptions = <K extends keyof HTMLElementTagNameMap>(
    tagName: K,
    options?: ElementCreationOptions
): HTMLElementTagNameMap[K] => {
    const element = document.createElement(tagName);

    if (options) {
        if (options.id) {
            element.id = options.id;
        }

        if (options.className) {
            element.className = options.className;
        }

        if (options.attributes) {
            Object.keys(options.attributes).forEach(attrName => {
                element.setAttribute(attrName, options.attributes[attrName]);
            });
        }

        if (options.style) {
            Object.assign(element.style, options.style);
        }

        if (options.eventListeners) {
            Object.keys(options.eventListeners).forEach(event => {
                element.addEventListener(event, options.eventListeners[event]);
            });
        }

        if (options.textContent) {
            element.textContent = options.textContent;
        }
    }

    return element;
};

