const express = require('express');
const fs = require('fs');
const path = require('path');
const marked = require('marked');

const app = express();

app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

const publicFolderPath = path.join(__dirname, '../public');

// Function to read files recursively and construct fileList array
const createFileList = (dir, fileList = []) => {
    const files = fs.readdirSync(dir);
    files.forEach(file => {
        const filePath = path.join(dir, file);
        const relativePath = path.relative(publicFolderPath, filePath);
        const stats = fs.statSync(filePath);
        if (stats.isDirectory()) {
            createFileList(filePath, fileList);
        } else {
            fileList.push({
                name: relativePath,
                path: relativePath
            });
        }
    });
    return fileList;
};

// Utility function to get HTML content for a given MD file path
const getFileHtmlContent = (filePath) => {
    try {
        const data = fs.readFileSync(filePath, 'utf8');
        return marked(data);
    } catch (err) {
        console.error('Error reading file:', err);
        return null;
    }
};

// Route to render the file list and optionally render selected MD file as HTML
app.get('/', (req, res) => {
    const fileList = createFileList(publicFolderPath);
    let htmlContent = null;

    // Check if a specific MD file is requested
    if (req.query.filename) {
        const filename = req.query.filename;
        const filePath = path.join(publicFolderPath, filename);
        htmlContent = getFileHtmlContent(filePath);

        // Set the 'selected' property for the selected file
        fileList.forEach(file => {
            file.selected = (file.path === filename);
        });
    }

    res.render('index', { fileList, htmlContent });
