```java
import graphql.GraphQL;
import graphql.schema.DataFetchingEnvironment;
import graphql.schema.GraphQLObjectType;
import graphql.schema.GraphQLSchema;
import graphql.schema.SelectedField;
import graphql.schema.idl.RuntimeWiring;
import graphql.schema.idl.SchemaGenerator;
import graphql.schema.idl.SchemaParser;
import graphql.schema.idl.TypeDefinitionRegistry;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.stereotype.Controller;

import java.util.List;
import java.util.Map;

@Controller
public class GraphQLController {

    private final SupplierGraphQLResolver supplierGraphQLResolver;

    @Autowired
    public GraphQLController(SupplierGraphQLResolver supplierGraphQLResolver) {
        this.supplierGraphQLResolver = supplierGraphQLResolver;
    }

    @Bean
    public GraphQL graphQL() {
        // Parse your GraphQL schema
        String schema = "your-graphql-schema.graphqls"; // Path to your GraphQL schema file
        TypeDefinitionRegistry typeRegistry = new SchemaParser().parse(new ClassPathResource(schema).getInputStream());
        RuntimeWiring runtimeWiring = buildRuntimeWiring();

        // Create the GraphQL schema
        GraphQLSchema graphQLSchema = new SchemaGenerator().makeExecutableSchema(typeRegistry, runtimeWiring);

        return GraphQL.newGraphQL(graphQLSchema).build();
    }

    private RuntimeWiring buildRuntimeWiring() {
        return RuntimeWiring.newRuntimeWiring()
                .type("Query", builder -> builder
                        .dataFetcher("getAllSuppliers", environment -> supplierGraphQLResolver.getAllSuppliers())
                        .dataFetcher("getSupplierById", environment -> {
                            String supplierId = environment.getArgument("supplierId");
                            return supplierGraphQLResolver.getSupplierById(supplierId);
                        })
                )
                .type("Mutation", builder -> builder
                        .dataFetcher("createSupplier", environment -> {
                            Map<String, Object> input = environment.getArgument("input");
                            return supplierGraphQLResolver.createSupplier(input);
                        })
                        .dataFetcher("updateSupplier", environment -> {
                            String supplierId = environment.getArgument("supplierId");
                            Map<String, Object> input = environment.getArgument("input");
                            return supplierGraphQLResolver.updateSupplier(supplierId, input);
                        })
                        .dataFetcher("deleteSupplier", environment -> {
                            String supplierId = environment.getArgument("supplierId");
                            return supplierGraphQLResolver.deleteSupplier(supplierId);
                        })
                )
                .build();
    }

    // Custom resolver methods can be added here if needed

}
```

