                Optional<String> sampleString = Optional.ofNullable(input);

                // Print results
                System.out.println(reverseString.perform(sampleString));
                System.out.println(palindromeResult.perform(sampleString));

                System.out.println("\nEnding test: '" + input + "' \n=====================");

            } catch (InvalidInputException e) {
                System.err.println("Input: '" + input + "', Error: " + e.getMessage());
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
