private static int factorialIterative(int val) {
    // Handle edge cases (factorial of 0 and 1 is 1)
    if (val < 1) {
        return 1;
    }

    return java.util.stream.IntStream.rangeClosed(2, val)
            .reduce(1, (a, b) -> a * b); // Multiply all numbers from 2 to 'val'
