        // Check if conversation was found
        if (!cgptFile.conversations || cgptFile.conversations.length === 0) {
            return { error: 'Conversation not found', status: 404 };
        }

        return {
            conversation: cgptFile.conversations[0], // Return only the matched conversation
            messages: cgptFile.messages || [],       // Return matched messages
        };
    } catch (err) {
        console.error(err);
        throw err;
    }
