```javascript
import React, { useState } from 'react';

const FruitSelector = () => {
  const [selectedFruits, setSelectedFruits] = useState([]);

  // Array of individual fruit objects
  const names = [
    { id: 1, name: 'Apple' },
    { id: 2, name: 'Banana' },
    { id: 3, name: 'Orange' },
    { id: 4, name: 'Grapes' },
    { id: 5, name: 'Mango' }
  ];

  // Handle individual checkbox selection
  const handleCheckboxChange = (event) => {
    const fruitName = event.target.value;
    setSelectedFruits((prevSelectedFruits) =>
      event.target.checked
        ? [...prevSelectedFruits, fruitName]
        : prevSelectedFruits.filter((fruit) => fruit !== fruitName)
    );
  };

  // Handle "All Fruits" checkbox selection
  const handleSelectAllChange = (event) => {
    if (event.target.checked) {
      setSelectedFruits(names.map((fruit) => fruit.name));
    } else {
      setSelectedFruits([]);
    }
  };

  // Check if "All Fruits" should be selected
  const isAllSelected = selectedFruits.length === names.length;

  return (
    <div>
      <h3>Select Fruits</h3>

      {/* All Fruits Checkbox */}
      <label>
        <input
          type="checkbox"
          checked={isAllSelected}
          onChange={handleSelectAllChange}
        />
        All Fruits
      </label>

      {/* Individual Fruit Checkboxes */}
      <div>
        {names.map((fruit) => (
          <label key={fruit.id}>
            <input
              type="checkbox"
              value={fruit.name}
              checked={selectedFruits.includes(fruit.name)}
              onChange={handleCheckboxChange}
            />
            {fruit.name}
          </label>
        ))}
      </div>

      {/* Display Selected Fruits */}
      <div>
        <h4>Selected Fruits:</h4>
        <label>{isAllSelected ? 'All Fruits' : selectedFruits.join(', ') || 'None'}</label>
      </div>
    </div>
  );
};

export default FruitSelector;
```

