package com.coding.practice.interview.questions.leetcode.q12;

import java.util.LinkedList;

public class Solution {
    public boolean isValid(String s) {
//        boolean valid=false;

        LinkedList<Character> characters = new LinkedList<>();
        Character lastCh = null;
        for (Character ch : s.toCharArray()) {
            switch (ch) {
                case '(':
                case '{':
                case '[':
                    characters.add(ch);
                    System.out.printf("Pushing %s, current state: %s %n", ch, characters);
                    break;
                case ')':
                    lastCh = characters.peekLast();
                    if (lastCh != null && lastCh == '(') {
                        characters.pop();
                        System.out.printf("Popping %s, current state: %s %n", ch, characters);
                    }
                    break;
                case '}':
                    lastCh = characters.peekLast();
                    if (lastCh != null && lastCh == '{') {
                        characters.pop();
                        System.out.printf("Popping %s, current state: %s %n", ch, characters);
                    }
                    break;
                case ']':
                    lastCh = characters.peekLast();
                    if (lastCh != null && lastCh == '[') {
                        characters.pop();
                        System.out.printf("Popping %s, current state: %s %n", ch, characters);
                    }
                    break;
                default:
                    break;
            }
        }


        return characters.isEmpty();
    }

    public static void main(String[] args) {
        String[] arr = new String[]{
//                "()",
//                "()[]{}",
//                "(]",
                "([])"
        };

        Solution sol = new Solution();

        for (String s : arr) {
            run(sol, s);
        }
    }

    private static void run(Solution sol, String s) {
        System.out.println("Input string: " + s + " is valid: " + sol.isValid(s));
    }
}

