/**
 * @param {string} s
 * @return {boolean}
 */
var isPalindrome = function(s) {
    // Step 1: Filter out non-alphanumeric characters and convert to lowercase
    let filtered = '';
    
    for (let c of s) {
        if (/[a-zA-Z0-9]/.test(c)) {
            filtered += c.toLowerCase();
        }
    }

    // Step 2: Check if the filtered string is a palindrome
    let left = 0, right = filtered.length - 1;
    
    while (left < right) {
        if (filtered[left] !== filtered[right]) {
            return false;
        }
        left++;
        right--;
    }
    
    return true;
};

