  frontend: "ReactJS",
  backend: "Spring Boot",
  database: "MongoDB",
};

renderCard({
  title: "Tech Stack Details",
  objectToBeRendered: techStackObject,
});
``` 

This approach resolves type errors and ensures type safety while maintaining flexibility.

Yes, it's possible to get both the keys and values of a TypeScript `enum`. However, the approach depends on whether the enum is **string-based** or **number-based**:

---

### For **String Enums**
String enums only map keys to values (and not the other way around). Here's how you can retrieve both keys and values:

```typescript
export enum Companies {
  GreenApple_WebWare = "greenapple-webware",
  HCL_Infosystems = "hcl-infosystems-limited",
  Novelvox = "novelvox-software-india-private-limited",
  Concentrix = "concentrix-daksh-services-india-private-limited",
  Dhani_Stocks = "dhani-stocks-limited",
  RSystems = "rsystems-international-private-limited",
  EVC_Ventures = "evc-ventures",
  Zycus_Infotech = "zycus-infotech-private-limited",
}

// Getting keys and values:
const getEnumKeysAndValues = <T>(enumObject: T) => {
  return Object.entries(enumObject).map(([key, value]) => ({ key, value }));
};

const companiesKeyValue = getEnumKeysAndValues(Companies);
console.log(companiesKeyValue);
```

**Output**:
```json
[
  { "key": "GreenApple_WebWare", "value": "greenapple-webware" },
  { "key": "HCL_Infosystems", "value": "hcl-infosystems-limited" },
  { "key": "Novelvox", "value": "novelvox-software-india-private-limited" },
  { "key": "Concentrix", "value": "concentrix-daksh-services-india-private-limited" },
  { "key": "Dhani_Stocks", "value": "dhani-stocks-limited" },
  { "key": "RSystems", "value": "rsystems-international-private-limited" },
  { "key": "EVC_Ventures", "value": "evc-ventures" },
  { "key": "Zycus_Infotech", "value": "zycus-infotech-private-limited" }
]
```

---

### For **Numeric Enums**
Numeric enums in TypeScript are **bidirectional**. This means you can map from key to value and also from value to key. To get both, you can use `Object.keys` and filter out the numeric indexes:

```typescript
enum NumericEnum {
  FIRST = 1,
  SECOND = 2,
  THIRD = 3,
}

// Getting keys and values:
const getNumericEnumKeysAndValues = <T>(enumObject: T) => {
  return Object.keys(enumObject)
    .filter((key) => isNaN(Number(key))) // Filter out numeric indexes
    .map((key) => ({
      key,
      value: (enumObject as any)[key],
    }));
};

const numericEnumKeyValue = getNumericEnumKeysAndValues(NumericEnum);
console.log(numericEnumKeyValue);
```

**Output**:
```json
[
  { "key": "FIRST", "value": 1 },
  { "key": "SECOND", "value": 2 },
  { "key": "THIRD", "value": 3 }
]
```

---

### Key Differences Between String and Numeric Enums:
- **String Enums**: Only map keys to values (one-directional).
- **Numeric Enums**: Are bidirectional, allowing both key-to-value and value-to-key mappings.

---

### Use Case for `prepareData` with Both Keys and Values:
You can modify the `prepareData` function to use both the keys and values of the enum:

```typescript
const prepareData = (): CompanyData[] => {
  return Object.entries(Companies).map(([key, uniqueId]) => {
    const data: CompanyData = {
      uniqueId: uniqueId as string,
      projects: CompanyProjects[uniqueId as string],
      ...CompanyBasicDetails[uniqueId as string],
    };
    return data;
  });
};
```

This way, you can access both `key` (e.g., `GreenApple_WebWare`) and `uniqueId` (e.g., `greenapple-webware`).

Here's the solution to the problem of finding two indices such that their corresponding numbers in an array add up to a given target:

### Code

```java
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        // A map to store the value and its corresponding index
        Map<Integer, Integer> numToIndex = new HashMap<>();

        // Iterate through the array
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i]; // Find the complement

            // Check if the complement is already in the map
            if (numToIndex.containsKey(complement)) {
                // Return the indices of the two numbers
                return new int[]{numToIndex.get(complement), i};
            }

            // Add the current number and its index to the map
            numToIndex.put(nums[i], i);
        }

        // If no solution is found, throw an exception (should not happen)
        throw new IllegalArgumentException("No two sum solution");
    }
}
```

---

### Explanation
1. **HashMap for Fast Lookup**:
   - A `HashMap` is used to store each number as the key and its index as the value.

2. **Complement Check**:
   - For each number in the array, compute its complement with respect to the target (`target - nums[i]`).
   - Check if the complement exists in the `HashMap`. If it does, the current index and the stored index form the solution.

3. **Add to Map**:
   - If the complement is not found, store the current number and its index in the map for future lookups.

4. **Return Indices**:
   - Return the indices of the current number and its complement if a match is found.

5. **Guaranteed Solution**:
   - The problem guarantees that a solution exists, so no need for additional checks beyond the complement lookup.

---

### Example
#### Input:
```java
int[] nums = {2, 7, 11, 15};
int target = 9;
```

#### Execution:
- Iteration 1:
  - Current number: `2`, Complement: `7`
  - Map: `{2: 0}`

- Iteration 2:
  - Current number: `7`, Complement: `2` (found in map)
  - Return `[0, 1]`

#### Output:
```java
[0, 1]
```

---

### Complexity
1. **Time Complexity**:
   - O(n): Each element is processed once.
2. **Space Complexity**:
   - O(n): For the `HashMap`.

This approach is efficient and works well for the given problem constraints.

Yes, it is generally necessary to call `executorService.shutdown()` when you're done using an `ExecutorService`. This method initiates an orderly shutdown of the executor, in which previously submitted tasks are executed, but no new tasks will be accepted.

### Why is it necessary?

1. **Resource Management**: An `ExecutorService` typically uses a pool of threads. If you don't shut it down, those threads will remain active and consume system resources like memory and CPU.

2. **Graceful Shutdown**: `shutdown()` allows the executor to finish executing all the submitted tasks before it stops. Without calling `shutdown()`, the JVM may not exit because the executor's threads are still running in the background.

3. **Avoiding Memory Leaks**: Not shutting down an `ExecutorService` may lead to memory leaks because the threads and associated resources are not released properly.

### What if you don't call `shutdown()`?

- **JVM Won't Exit**: If you don't shut down the executor, the JVM may keep running indefinitely, waiting for the threads to finish.
- **Resource Leaks**: The resources (threads, memory) associated with the executor might not be released, leading to resource exhaustion over time.

### Alternatives to `shutdown()`

- **shutdownNow()**: This method attempts to stop all actively executing tasks, halts the processing of waiting tasks, and returns a list of the tasks that were awaiting execution. This method does not wait for actively executing tasks to terminate, which can lead to incomplete tasks.

- **awaitTermination()**: After calling `shutdown()`, you can call `awaitTermination()` to block until all tasks have completed execution after a shutdown request, or the timeout occurs, or the current thread is interrupted, whichever happens first.

### Example with `shutdown()` and `awaitTermination()`

```java
import java.util.concurrent.*;

public class ExecutorServiceExample {

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(2);

        executorService.submit(() -> {
            try {
                TimeUnit.SECONDS.sleep(2);
                System.out.println("Task 1 completed");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executorService.submit(() -> {
            try {
                TimeUnit.SECONDS.sleep(1);
                System.out.println("Task 2 completed");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executorService.shutdown(); // Initiates an orderly shutdown

        try {
            // Blocks until all tasks have completed execution or the timeout occurs
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow(); // Force shutdown if tasks take too long
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow(); // Force shutdown on interruption
        }

        System.out.println("Executor service shut down");
    }
}
```

In summary, calling `shutdown()` is important for proper resource management and ensuring that the JVM can exit cleanly after your program has finished executing.

Here's the equivalent JavaScript and TypeScript code for the provided Java code that checks if a string is a palindrome after filtering non-alphanumeric characters and converting the string to lowercase.

### JavaScript Code:

```javascript
function isPalindrome(s) {
    // Step 1: Filter out non-alphanumeric characters and convert to lowercase
    let filtered = '';

    for (let c of s) {
        if (/[a-zA-Z0-9]/.test(c)) {
            filtered += c.toLowerCase();
        }
    }

    // Step 2: Check if the filtered string is a palindrome
    let left = 0, right = filtered.length - 1;

    while (left < right) {
        if (filtered[left] !== filtered[right]) {
            return false;
        }
        left++;
        right--;
    }

    return true;
}

// Test Cases
console.log(isPalindrome("A man, a plan, a canal: Panama")); // true
console.log(isPalindrome("race a car")); // false
console.log(isPalindrome(" ")); // true
```

