const calculateCTC = (
  hourlyWage: number,
  workingDaysInMonth: number = DEFAULT_WORKING_DAYS_IN_MONTH,
  workingHoursPerDay: number = DEFAULT_WORKING_HOURS_PER_DAY
) => {
  const yearlyCTC = hourlyWage * workingDaysInMonth * workingHoursPerDay * 12;
  return { hourlyWage, ctc: yearlyCTC };
};

