const GoldRateCalculator = () => {
  const goldData = GOLD_RATE.data;

  const [combinedState, setCombinedState] = useState({
    selectedYear: "",
    amount: 1,
    targetAmount: 0,
    selectedTargetYear: "",
    formula: ""
  });

