### `loadYAMLData.ts`
```ts
import yaml from "js-yaml";

export interface LoadYAMLResponse<T> {
  jsonData: T | null;
  isError: boolean;
  errorMessage: string | null;
}

export const loadYAMLData = <T,>(yamlText: string): LoadYAMLResponse<T> => {
  try {
    const jsonData = yaml.load(yamlText) as T;
    return {
      jsonData,
      isError: false,
      errorMessage: null,
    };
  } catch (e: any) {
    const error = e.mark
      ? `Error parsing YAML at line ${e.mark.line + 1}: ${e.message}`
      : `Error parsing YAML: ${e.message}`;
    return {
      jsonData: null,
      isError: true,
      errorMessage: error,
    };
  }
};
```

