To make the modal resizable, we need to add some additional functionality. Since React doesn't have built-in support for resizable components, we'll need to utilize a resizable component library or implement the resizing functionality ourselves.

Here's an example of how you might integrate resizable functionality using the `react-resizable` library:

```jsx
import React, { useEffect } from 'react';
import { Resizable } from 'react-resizable';

const withModal = (ModalComponent) => {
  return ({ isOpen, onClose, onSave }) => {
    const handleSubmit = (formData) => {
      onSave(formData);
      onClose();
    };

    useEffect(() => {
      const handleKeyDown = (event) => {
        if (event.key === 'Escape') {
          onClose();
        }
      };

      if (isOpen) {
        document.addEventListener('keydown', handleKeyDown);
      }

      return () => {
        document.removeEventListener('keydown', handleKeyDown);
      };
    }, [isOpen, onClose]);

    const onResize = (event, { size }) => {
      // Handle resize event here
    };

    return (
      <div style={modalBackdropStyle}>
        {isOpen && (
          <Resizable
            defaultSize={{ width: 400, height: 200 }}
            onResize={onResize}
          >
            <div style={modalContainerStyle}>
              <div style={modalContentStyle}>
                <ModalComponent onClose={onClose} onSave={handleSubmit} />
                <button
                  style={closeButtonStyle}
                  onClick={onClose}
                  aria-label="Close"
                >
                  &#10005;
                </button>
              </div>
            </div>
          </Resizable>
        )}
      </div>
    );
  };
};

const modalBackdropStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100%',
  height: '100%',
  background: 'rgba(0, 0, 0, 0.5)',
  zIndex: 1000,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
};

const modalContainerStyle = {
  background: 'green',
  borderRadius: '10px',
