import org.springframework.scheduling.support.CronTrigger;
import org.springframework.stereotype.Service;

import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;

@Service
public class NextDateService {

    public String calculateNextDate(String inputDate) throws Exception {
        SimpleDateFormat dateFormat = new SimpleDateFormat("dd-MMM-yyyy");
        Date date = dateFormat.parse(inputDate);

        // Define a DAILY cron expression
        String cronExpression = "0 0 0 * * ?";

        CronTrigger cronTrigger = new CronTrigger(cronExpression);
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);

        // Calculate the next date
        Date nextDate = cronTrigger.nextExecutionTime(calendar.getTime());

        // Format the next date as a string
        String nextDateStr = dateFormat.format(nextDate);

        return nextDateStr;
    }
}
