    word: String,
    meanings: [{
        part_of_speech: String,
        definition: String,
        example_sentences: [String]
    }],
    synonyms: [String],
    antonyms: [String]
});
const Word = mongoose.model('Word', wordSchema);

// Express endpoint to store a word
app.post('/words', async (req, res) => {
    try {
        // Create a new word entry
        const newWord = new Word(req.body);
        // Save the word entry to the database
        await newWord.save();
        res.status(201).send('Word entry stored successfully');
    } catch (err) {
        console.error(err);
        res.status(500).send('Error storing word entry');
    }
});

// Start the Express server
