  createCategory,
  getCategories,
  getCategoryByUniqueId,
  updateCategoryByUniqueId,
  deleteCategoryByUniqueId,
  getQuestionsByCategoryId,
  saveQuestionForCategoryId,
  updateQuestionForCategoryId,
  getQuestionByCategoryIdAndQuesId,
};
