    try {
        const memoryMaps = await MemoryMap.find({ tags: tagId }).select({
            uniqueId: 1,
            name: 1,
        });
        return memoryMaps;
    } catch (error) {
        console.error(error);
        throw new Error(`Error retrieving MemoryMaps with tagId ${tagId}: ${error.message}`);
    }
}

module.exports = {
    saveMemoryMap,
    updateMemoryMap,
    fetchAllMemoryMaps,
