const avblResList = ["index", "categories"];
const remoteCSSStyles = {
    dark: "https://cdnjs.cloudflare.com/ajax/libs/github-markdown-css/5.5.1/github-markdown.min.css",
    light:
        "https://cdnjs.cloudflare.com/ajax/libs/github-markdown-css/5.5.1/github-markdown-light.min.css",
};

const wrapHTMLContent = (styleToApply, htmlContent) => {
    return `<!DOCTYPE html> <html lang="en">
    <head> <link rel="stylesheet" href="${styleToApply}" /></head>
     <body class="markdown-body"> ${htmlContent} </body>
    </html>`;
}

// Endpoint for /help?out=html
router.get("/help", (req, res) => {
    const { resource, viewStyles } = req.query;
    let fileName = resource || "index";
    const styleToApply =
        remoteCSSStyles[
        viewStyles && ["dark", "light"].includes(viewStyles.trim().toLowerCase())
            ? viewStyles.trim().toLowerCase()
            : "dark"
        ];
    console.log(`styleToApply : ${styleToApply}`)
    // check if documentation avaiable for requested resource.
    const docAvbl = avblResList.includes(fileName.toLowerCase());
    // console.log(`documentation for resource :'${fileName}' is ${docAvbl?'':'not'} available`)
    if (docAvbl) {
        const htmlContent = getFileHtmlContent(`${fileName}.md`);
        res.send(wrapHTMLContent(styleToApply, htmlContent));
    } else {
        const htmlContent = `<div> 
                                Requested resource <b>${fileName}</b> not available! <br/>
                                <a href="/help">Back to documentation </a>
                            </div>`;
        res.send(wrapHTMLContent(styleToApply, htmlContent));
    }
});

