    const selectedIndex = flatTopicList.findIndex((topic) => topic.uniqueId === selectedTopicUId);
    if (selectedIndex < 0 ) {
      return null
    };
    const prevIndex = (selectedIndex + dataLength - 1) % dataLength;
    return flatTopicList[prevIndex].uniqueId;
