import java.util.List;
import java.util.stream.Collectors;

public class ListFlattener {

    /**
     * Flattens a list of lists into a single list.
     *
     * @param lists the list of lists to be flattened
     * @param <T>   the type of elements in the lists
     * @return a single list containing all the elements from the nested lists
     */
    public <T> List<T> flatten(List<List<T>> lists) {
        return lists.stream()
                    .flatMap(List::stream)
                    .collect(Collectors.toList());
    }

    public static void main(String[] args) {
        ListFlattener flattener = new ListFlattener();
        List<List<Integer>> listOfLists = List.of(
            List.of(1, 2, 3),
            List.of(4, 5),
            List.of(6, 7, 8, 9)
        );
        List<Integer> flattenedList = flattener.flatten(listOfLists);
        System.out.println(flattenedList); // Output: [1, 2, 3, 4, 5, 6, 7, 8, 9]
    }
}
```

