class HashMapSorterTest {

    @Test
    void testSortByValue() {
        HashMap<String, Integer> hm = new HashMap<>();
        hm.put("Math", 98);
        hm.put("Data Structure", 85);
        hm.put("Database", 91);
        hm.put("Java", 95);
        hm.put("Operating System", 79);
        hm.put("Networking", 80);

        HashMap<String, Integer> sortedMap = HashMapSorter.sortByValue(hm);

        assertEquals(79, sortedMap.get("Operating System"));
        assertEquals(80, sortedMap.get("Networking"));
        assertEquals(85, sortedMap.get("Data Structure"));
        assertEquals(91, sortedMap.get("Database"));
        assertEquals(95, sortedMap.get("Java"));
        assertEquals(98, sortedMap.get("Math"));
    }
}
