package com.p.examples.uncategorized;

import java.util.Scanner;

/**
 * This class provides a method to perform left rotation on an integer array.
 */
public class Solution {

    /**
     * Performs left rotation on the given integer array.
     *
     * @param a The integer array to rotate.
     * @param n The length of the array.
     * @param k The number of left rotations to perform.
     * @return The array after left rotation.
     */
    public static int[] arrayLeftRotation(int[] a, int n, int k) {

        int[] temp = new int[n];
        int[] temp1 = new int[n];
        for (int i = 0; i < n; i++) {
            temp[i] = a[i];
            temp1[i] = a[i];
        }

        for (int j = 1; j <= k; j++) {
            for (int i = 0; i < n; i++) {
                temp1[i] = temp[(i + 1) % n];
            }
            temp = temp1.clone();
        }

        return temp;
