#### API Gateway (api-gateway.js)

```javascript
const express = require('express');
const axios = require('axios');
const { createProxyMiddleware } = require('http-proxy-middleware');

const app = express();
const port = 3000;
const serviceDiscoveryUrl = 'http://localhost:4000/services';

let services = [];

const updateServices = async () => {
    try {
        const response = await axios.get(serviceDiscoveryUrl);
        services = response.data;
    } catch (error) {
        console.error('Failed to fetch services', error);
    }
};

const getServiceUrl = (name) => {
    const service = services.find(service => service.name === name);
    return service ? service.url : null;
};

// Update services every 10 seconds
setInterval(updateServices, 10000);

// Initial update
updateServices();

app.use('/topics', (req, res, next) => {
    const url = getServiceUrl('topics');
    if (url) {
        createProxyMiddleware({ target: url, changeOrigin: true })(req, res, next);
    } else {
        res.status(503).send('Service unavailable');
    }
});

app.use('/words', (req, res, next) => {
    const url = getServiceUrl('words');
    if (url) {
        createProxyMiddleware({ target: url, changeOrigin: true })(req, res, next);
    } else {
        res.status(503).send('Service unavailable');
    }
});

app.listen(port, () => console.log(`API Gateway listening on port ${port}!`));
```

