```jsx
import React, { useState } from 'react';
import prettier from 'prettier';

function HTMLFormatter() {
  const [unformattedHTML, setUnformattedHTML] = useState('');
  const [formattedHTML, setFormattedHTML] = useState('');

  const formatHTML = () => {
    try {
      const options = {
        parser: 'html',
        tabWidth: 2,
        useTabs: false,
        printWidth: 80,
        singleQuote: true,
        trailingComma: 'none',
      };

      const formatted = prettier.format(unformattedHTML, options);
      setFormattedHTML(formatted);
    } catch (error) {
      console.error('Error formatting HTML:', error);
    }
  };

  return (
    <div>
      <h2>HTML Formatter</h2>
      <div>
        <h3>Unformatted HTML</h3>
        <textarea
          rows={10}
          cols={50}
          value={unformattedHTML}
          onChange={(e) => setUnformattedHTML(e.target.value)}
        />
      </div>
      <div>
        <button onClick={formatHTML}>Format HTML</button>
      </div>
      {formattedHTML && (
        <div>
          <h3>Formatted HTML</h3>
          <pre>{formattedHTML}</pre>
        </div>
      )}
    </div>
  );
}

export default HTMLFormatter;
```

3. Use the `HTMLFormatter` component in your `App.js` (or equivalent):

```jsx
import React from 'react';
import HTMLFormatter from './HTMLFormatter';

function App() {
  return (
    <div>
      <HTMLFormatter />
    </div>
  );
}

export default App;
```

In this example, the `HTMLFormatter` component provides a textarea where you can input unformatted HTML. When you click the "Format HTML" button, the input HTML is processed using the `prettier` library with the specified options, and the formatted HTML is displayed below the button.

